// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 아이디 찾기" (a325a7b416484edfacf35d8f124d2277).
// 모양은 비밀번호 찾기 화면과 같은 공통 조각(components/findAccount)으로 맞춘다.
// #189: docs/ui-guide.md 공통 값(uiStyles, writer)으로 바꿨다.
import { useState, type FormEvent } from "react";
import { Link } from "react-router-dom";
import { findLoginId, type FindLoginIdResult } from "../api/auth";
import { getErrorMessage } from "../api/client";
import { INPUT_PATTERNS, INPUT_RULES, formatPhoneInput, toPhoneDigits } from "../api/member";
import "./FindId.css";
import AccountLinks from "../components/AccountLinks";
import AuthHeader from "../components/AuthHeader";
import Footer from "../components/Footer";
import { HEADER_BUTTON_CLASS, HEADER_BUTTON_COLOR } from "../components/headerStyles";
import {
  FieldHint,
  FieldLabel,
  FindCard,
  FindCardFooter,
  FindCardHeader,
  FindPageHeading,
  NoticeBox,
  StatusMessage,
} from "../components/findAccount/FindAccountParts";
import { buttonClass, INPUT, PAGE_BACKGROUND } from "../components/uiStyles";
import { formatDate } from "../components/writer";

type Result =
  { status: "empty" } | { status: "found"; data: FindLoginIdResult } | { status: "failed"; message: string };

const RESULT_TITLE = "조회된 아이디 정보";

export default function FindId() {
  const [nickname, setNickname] = useState("");
  const [phone, setPhone] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult] = useState<Result>({ status: "empty" });

  const nicknameValid = INPUT_PATTERNS.nickname.test(nickname);
  const phoneValid = INPUT_PATTERNS.phone.test(toPhoneDigits(phone));
  const canSubmit = nicknameValid && phoneValid && !submitting;

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!canSubmit) return;
    setSubmitting(true);
    try {
      const data = await findLoginId(nickname, toPhoneDigits(phone));
      setResult({ status: "found", data });
    } catch (err) {
      setResult({ status: "failed", message: getErrorMessage(err) });
    } finally {
      setSubmitting(false);
    }
  }

  const nicknameInvalid = nickname !== "" && !nicknameValid;
  const phoneInvalid = phone !== "" && !phoneValid;

  return (
    <div id="page-find-id">
      <div className={`${PAGE_BACKGROUND} min-h-screen flex flex-col justify-between text-devin-ink antialiased`}>
        <AuthHeader>
          <Link className={`${HEADER_BUTTON_CLASS} ${HEADER_BUTTON_COLOR.white}`} to="/login">
            로그인
          </Link>
          <Link className={`${HEADER_BUTTON_CLASS} ${HEADER_BUTTON_COLOR.yellow}`} to="/signup">
            회원가입
          </Link>
        </AuthHeader>

        <main className="flex-1 max-w-6xl w-full mx-auto px-4 py-10 flex flex-col justify-center">
          <FindPageHeading
            description="가입할 때 등록한 닉네임과 전화번호로 본인 확인을 하면 아이디를 볼 수 있어요."
            title="아이디 찾기"
          />

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 items-stretch">
            {/* 왼쪽 카드: 회원 정보 입력 */}
            <FindCard className="justify-between">
              <div>
                <FindCardHeader title="회원 정보 입력" />

                <form className="space-y-5" noValidate onSubmit={handleSubmit}>
                  <div>
                    <FieldLabel htmlFor="user-name">닉네임</FieldLabel>
                    <input
                      aria-invalid={nicknameInvalid}
                      autoComplete="nickname"
                      className={`${INPUT.base} ${nicknameInvalid ? INPUT.error : ""}`}
                      id="user-name"
                      maxLength={10}
                      onChange={(e) => setNickname(e.target.value)}
                      placeholder="닉네임 입력"
                      type="text"
                      value={nickname}
                    />
                    <FieldHint tone={nicknameInvalid ? "error" : "idle"}>
                      {nicknameInvalid ? INPUT_RULES.nickname : "가입할 때 등록한 닉네임"}
                    </FieldHint>
                  </div>
                  <div>
                    <FieldLabel htmlFor="user-phone">전화번호</FieldLabel>
                    <input
                      aria-invalid={phoneInvalid}
                      autoComplete="tel"
                      className={`${INPUT.base} ${phoneInvalid ? INPUT.error : ""} font-mono tracking-wider`}
                      id="user-phone"
                      inputMode="numeric"
                      maxLength={13}
                      onChange={(e) => setPhone(formatPhoneInput(e.target.value))}
                      placeholder="010-0000-0000"
                      type="tel"
                      value={phone}
                    />
                    <FieldHint tone={phoneInvalid ? "error" : "idle"}>
                      {phoneInvalid
                        ? "01로 시작하는 10~11자리 숫자를 입력해 주세요."
                        : "숫자만 입력하면 하이픈이 자동으로 들어가요."}
                    </FieldHint>
                  </div>

                  <NoticeBox>보안을 위해 아이디는 앞 3자리만 보여 주고 나머지는 * 로 가려요.</NoticeBox>

                  <button className={`${buttonClass("primary")} w-full`} disabled={!canSubmit} type="submit">
                    {submitting ? "찾는 중..." : "아이디 찾기"}
                  </button>
                </form>
              </div>

              <FindCardFooter>
                <AccountLinks current="find-id" />
              </FindCardFooter>
            </FindCard>

            {/* 오른쪽 카드: 조회 결과 (조회 전 / 찾음 / 일치하는 회원 없음) */}
            <FindCard className="min-h-[360px]">
              <div aria-live="polite" className="flex-1 flex flex-col">
                <FindCardHeader title={RESULT_TITLE} />

                {result.status === "empty" && (
                  <StatusMessage icon="search" title="아직 조회한 정보가 없어요">
                    왼쪽에 닉네임과 전화번호를 입력하고
                    <br />
                    [아이디 찾기]를 누르면 여기에 보여 줘요.
                  </StatusMessage>
                )}

                {result.status === "found" && (
                  <>
                    <div className="mb-4 space-y-1">
                      <p className="text-sm font-bold text-devin-ink">
                        <span className="font-extrabold">{result.data.nickname}</span>
                        {" 회원님의 아이디예요."}
                      </p>
                      <p className="text-xs font-medium text-devin-gray">계정 보안을 위해 아이디 일부를 가렸어요.</p>
                    </div>
                    <div className="mb-6 p-4 bg-devin-bg border-devin border-devin-ink rounded-xl">
                      <div className="flex items-center justify-between gap-2 mb-2 text-xs font-bold text-devin-gray">
                        <span>아이디</span>
                        <span className="tabular-nums">가입일 {formatDate(result.data.createdAt)}</span>
                      </div>
                      <div className="px-4 py-2.5 bg-devin-paper border-devin border-devin-ink rounded-lg">
                        <span className="text-base font-mono font-extrabold tracking-widest text-devin-ink break-all">
                          {result.data.maskedLoginId}
                        </span>
                      </div>
                    </div>
                    <div className="space-y-3 mt-auto">
                      <Link className={`${buttonClass("secondary")} w-full`} to="/login">
                        로그인하러 가기
                        <span className="material-symbols-outlined text-[18px] leading-none" aria-hidden="true">
                          arrow_forward
                        </span>
                      </Link>
                      <Link className={`${buttonClass("secondary")} w-full`} to="/find-password">
                        비밀번호 찾기
                      </Link>
                    </div>
                  </>
                )}

                {result.status === "failed" && (
                  <>
                    <StatusMessage icon="error" title={result.message} tone="error">
                      닉네임과 전화번호를 다시 확인해 주세요.
                      <br />
                      가입한 적이 없다면 회원가입을 해 주세요.
                    </StatusMessage>
                    <Link className={`${buttonClass("accent")} w-full mt-auto`} to="/signup">
                      회원가입하러 가기
                    </Link>
                  </>
                )}
              </div>
            </FindCard>
          </div>
        </main>

        <Footer />
      </div>
    </div>
  );
}
